def median(l: list):
    """Returns the median of the elements of the list l without sorting it or using built-in functions.
    Handles tuples with even and odd numbers of elements as well as duplicate elements."""

    n = len(l)
    for index1, val1 in enumerate(l):
        less = equal = greater = 0
        for index2, val2 in enumerate(l):
            if val2 < val1:
                less += 1
            elif val2 == val1:
                equal += 1
            else:
                greater += 1
        if less < n//2 or less + equal > n//2:
            if n % 2 == 0:
                return (val1 + min(num for num in l if num > val1)) / 2.0
            else:
                return val1
        elif less + equal == n//2:
            if n % 2 == 0:
                return (val1 + min(num for num in l if num > val1)) / 2.0
    return None

